from collections import deque
grid = [[0, 0, 0],
        [1, 1, 0],
        [0, 0, 0]]
start, goal = (0, 0), (2, 0)
queue = deque([(start, 0)])
seen = {start}
while queue:
    (r, c), steps = queue.popleft()
    if (r, c) == goal:
        print("Shortest path:", steps, "steps")
        break
    for nr, nc in [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]:
        if 0 <= nr < 3 and 0 <= nc < 3 and grid[nr][nc] == 0 and (nr, nc) not in seen:
            seen.add((nr, nc))
            queue.append(((nr, nc), steps + 1))

from collections import deque
graph = {"A": ["B", "C"], "B": ["D"], "C": ["D"], "D": []}
queue = deque(["A"])
seen = {"A"}
order = []
while queue:
    node = queue.pop()
    order.append(node)
    for nxt in graph[node]:
        if nxt not in seen:
            seen.add(nxt)
            queue.append(nxt)
print(order)

